Dear Professor Finn,<div><br></div><div>Let me know the following formulation works to resolve the particular problem?</div><div><br></div><div>P.S. I also conversed with Dr. Rue. But it seems the current INLA version does not support me A.local. I was looking an alternate way to resolve this problem.</div><div><br></div><div>&quot;##</div><br>set.seed(42)<br><br># ---- Parameters ----<br>N_img      &lt;- 80       # number of distinct images<br>repeats    &lt;- 10        # repeats per image<br>N_trials   &lt;- N_img * repeats<br>T          &lt;- 100      # time bins per trial<br>grid_size  &lt;- 3        # 3x3 grid<br><br># ---- Stimuli X_{n,i,j} ----<br># grayscale intensities in [0,1]<br>X &lt;- array(runif(N_trials * grid_size * grid_size),<br>           dim = c(N_trials, grid_size, grid_size))<br><br># ---- Beta_{i,j,t} ----<br># Diagonals: strongly positive constant over time<br>beta_ijt &lt;- array(0, dim = c(grid_size, grid_size, T))<br>for (i in 1:grid_size) {<br>  for (j in 1:grid_size) {<br>    if (i == j) {<br>      beta_ijt[i, j, ] &lt;- 2.5 # + rnorm(T, mean = 0, sd = 0.05)  # diagonal excitatory<br>    } else {<br>      beta_ijt[i, j, ] &lt;- 0#-1.5 + rnorm(T, mean = 0, sd = 0.05) # off-diagonal inhibitory<br>    }<br>  }<br>}<br><br># ---- Per-trial random effect b_n ----<br>b_n &lt;- rnorm(N_trials, mean = 0, sd = 0.1)<br><br># ---- Baseline and simulate y_{n,t} ~ Poisson(exp(linear)) ----<br>beta0 &lt;- -2<br>y &lt;- matrix(0, nrow = N_trials, ncol = T)<br><br>for (n in 1:N_trials) {<br>  for (t in 1:T) {<br>    lin &lt;- beta0 + b_n[n]<br>    # add spatial contributions<br>    for (i in 1:grid_size) {<br>      for (j in 1:grid_size) {<br>        lin &lt;- lin + beta_ijt[i, j, t] * X[n, i, j]<br>      }<br>    }<br>    lambda_nt &lt;- exp(lin)<br>    y[n, t] &lt;- rpois(1, lambda = lambda_nt)<br>  }<br>}<br><br># ---- Build dataframe ----<br>library(dplyr)<br><br>df &lt;- expand.grid(<br>  trial = 1:N_trials,<br>  time  = 1:T<br>)<br>df$y &lt;- as.vector(y)<br><br># ---- Add image_id and rep_id ----<br>df$image_id &lt;- (df$trial - 1) %/% repeats + 1<br>df$rep_id   &lt;- (df$trial - 1) %% repeats + 1<br><br># ---- Add flattened stimulus features per trial ----<br>X_mat &lt;- matrix(NA, nrow = N_trials, ncol = grid_size * grid_size)<br>colnames(X_mat) &lt;- paste0(&quot;x_&quot;, rep(1:grid_size, each = grid_size), &quot;_&quot;, rep(1:grid_size, times = grid_size))<br>for (n in 1:N_trials) {<br>  X_mat[n, ] &lt;- as.vector(t(X[n, , ]))<br>}<br><br>df &lt;- cbind(df, df$trial %&gt;% sapply(function(tr) X_mat[tr, ]) %&gt;% t())<br>colnames(df)[(ncol(df) - ncol(X_mat) + 1):ncol(df)] &lt;- colnames(X_mat)<br><br># ---- Quick check ----<br>mean_beta &lt;- apply(beta_ijt, c(1, 2), mean)<br>print(&quot;Mean beta (3x3): diagonals should be large positive:&quot;)<br>print(round(mean_beta, 3))<br><br>diag_means &lt;- diag(mean_beta)<br>offdiag_means &lt;- mean(mean_beta[upper.tri(mean_beta) | lower.tri(mean_beta)])<br>cat(&quot;Diagonal means:&quot;, round(diag_means, 3), &quot;
&quot;)<br>cat(&quot;Average off-diagonal mean:&quot;, round(offdiag_means, 3), &quot;
&quot;)<br><br>cat(&quot;Overall mean spike count:&quot;, mean(df$y), &quot; (sd:&quot;, sd(df$y), &quot;)
&quot;)<br><br># ---- Optional: visualize beta ----<br>image(1:3, 1:3, mean_beta, main = &quot;Mean β across pixels&quot;, xlab = &quot;i&quot;, ylab = &quot;j&quot;)<br>contour(1:3, 1:3, mean_beta, add = TRUE)<br><br># ---- Check new columns ----<br>head(df)<br><br><br>### getting estimated by spde , model recovery<br><br><br>df_real &lt;- df %&gt;%<br>  rename(<br>    time_bin_num = time,<br>    firing_count = y<br>  )<br><br><br>df &lt;- df_real<br><br><br>library(INLA)<br>library(Matrix)<br><br># Identify pixel columns<br>pixel_cols &lt;- grep(&quot;^x_\d+_\d+$&quot;, colnames(df), value = TRUE)<br><br>#  Extract pixel coordinates<br>pixel_coords &lt;- do.call(rbind, lapply(pixel_cols, function(name) {<br>  x &lt;- as.numeric(sub(&quot;^x_(\d+)_\d+$&quot;, &quot;\1&quot;, name))<br>  y &lt;- as.numeric(sub(&quot;^x_\d+_(\d+)$&quot;, &quot;\1&quot;, name))<br>  c(x, y)<br>}))<br>colnames(pixel_coords) &lt;- c(&quot;x&quot;, &quot;y&quot;)<br><br># Build SPDE mesh<br>mesh &lt;- inla.mesh.2d(loc = pixel_coords, max.edge = c(1, 1), cutoff = 0.01)<br>spde &lt;- inla.spde2.matern(mesh = mesh, alpha = 2)<br><br>#  Projector matrix for pixels<br>A_pix &lt;- inla.spde.make.A(mesh = mesh, loc = pixel_coords)<br><br>#  Observation × SPDE design<br>X_spatial &lt;- as.matrix(df[, pixel_cols]) %*% A_pix<br><br>#  INLA stack with rep_id<br>stack &lt;- inla.stack(<br>  data = list(y = df$firing_count),<br>  A = list(1, X_spatial, 1),   # intercept + spatial field + rep_id<br>  effects = list(<br>    intercept = rep(1, nrow(df)),<br>    spatial_field = 1:spde$n.spde,<br>    rep_id = df$rep_id          # include rep_id here<br>  ),<br>  tag = &quot;spatial_stack&quot;<br>)<br># Assuming &#39;time_col&#39; is the column in df representing time (t)<br><br>#  Formula including rep_id as IID random effect<br>formula &lt;- y ~ 1 +<br>  f(rep_id, model = &quot;iid&quot;) +<br>  f(spatial_field, model = spde)<br><br>#  Fit the model<br>result &lt;- inla(<br>  formula,<br>  data = inla.stack.data(stack),<br>  family = &quot;poisson&quot;,<br>  control.predictor = list(A = inla.stack.A(stack), compute = TRUE),<br>  control.compute = list(dic = TRUE, waic = TRUE, config = TRUE),<br>  control.inla = list(strategy = &quot;simplified.laplace&quot;)<br>)<br><br><br>#  Posterior mean of spatial field ## beta retrival?<br>field_mean &lt;- result$summary.random$spatial_field$mean
